#!/usr/bin/env python3
"""Generate the Go schema literal from the cross-client source contract."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[2]
source = root / 'contracts/document.schema.json'
compact = json.dumps(json.loads(source.read_text()), ensure_ascii=False, separators=(',', ':'))
assert '`' not in compact
(root / 'server/internal/document/schema_generated.go').write_text(
    '// Code generated by tools/scripts/generate-document-schema.py; DO NOT EDIT.\n'
    'package document\n\n'
    '// SchemaJSON is the canonical cross-client structural contract.\n'
    'const SchemaJSON = `' + compact + '`\n')
